package com.nextrade.persistence.entity; import jakarta.persistence.*; import java.time.*; import java.util.*;
@Entity @Table(name="app_user",indexes={@Index(name="ux_user_username",columnList="username",unique=true),@Index(name="ux_user_email",columnList="email",unique=true)}) public class UserEntity { @Id private UUID id; @Column(nullable=false,length=50) private String username; @Column(nullable=false,length=255) private String email; @Column(nullable=false,length=255) private String passwordHash; @Column(nullable=false,length=30) private String role; @Column(nullable=false,length=30) private String status; @Column(nullable=false) private boolean emailVerified; @Column(nullable=false) private int failedAttempts; private Instant lockedUntil; @Version private long version; public UserEntity(){} public UUID getId(){return id;} public void setId(UUID v){id=v;} public String getUsername(){return username;} public void setUsername(String v){username=v;} public String getEmail(){return email;} public void setEmail(String v){email=v;} public String getPasswordHash(){return passwordHash;} public void setPasswordHash(String v){passwordHash=v;} public String getRole(){return role;} public void setRole(String v){role=v;} public String getStatus(){return status;} public void setStatus(String v){status=v;} public boolean isEmailVerified(){return emailVerified;} public void setEmailVerified(boolean v){emailVerified=v;} public int getFailedAttempts(){return failedAttempts;} public void setFailedAttempts(int v){failedAttempts=v;} public Instant getLockedUntil(){return lockedUntil;} public void setLockedUntil(Instant v){lockedUntil=v;} public long getVersion(){return version;} }
